     1→// Phase 1: Biometric Signal Collection
     2→// 타이핑 습관, 터치 압력, 심박수 수집
     3→
     4→use std::collections::VecDeque;
     5→
     6→/// 키스트로크 다이나믹스 (Keystroke Dynamics)
     7→/// 타이핑 속도, 키 간 시간차, 누르기 시간을 추적
     8→#[derive(Clone, Debug)]
     9→pub struct KeystrokeSignal {
    10→    pub key: char,
    11→    pub timestamp: u64,
    12→    pub press_duration: u64,  // 키를 누르고 있던 시간 (ms)
    13→    pub flight_time: u64,      // 이전 키와의 시간차 (ms)
    14→    pub pressure: f64,         // 누른 강도 (0.0~1.0)
    15→}
    16→
    17→/// 터치 압력 신호
    18→#[derive(Clone, Debug)]
    19→pub struct TouchSignal {
    20→    pub x: f64,               // X 좌표
    21→    pub y: f64,               // Y 좌표
    22→    pub pressure: f64,        // 터치 압력 (0.0~1.0)
    23→    pub timestamp: u64,
    24→    pub duration: u64,        // 터치 지속 시간 (ms)
    25→}
    26→
    27→/// 심박수 신호 (웨어러블)
    28→#[derive(Clone, Debug)]
    29→pub struct HeartRateSignal {
    30→    pub bpm: f64,             // 분당 박동수
    31→    pub timestamp: u64,
    32→    pub variability: f64,     // HRV (Heart Rate Variability) 0.0~1.0
    33→    pub confidence: f64,      // 측정 신뢰도 (0.0~1.0)
    34→}
    35→
    36→/// 통합 생체 신호
    37→#[derive(Clone, Debug)]
    38→pub enum BiometricSignal {
    39→    Keystroke(KeystrokeSignal),
    40→    Touch(TouchSignal),
    41→    HeartRate(HeartRateSignal),
    42→}
    43→
    44→/// 생체 신호 수집기
    45→#[derive(Clone, Debug)]
    46→pub struct BiometricCollector {
    47→    pub keystroke_buffer: VecDeque<KeystrokeSignal>,
    48→    pub touch_buffer: VecDeque<TouchSignal>,
    49→    pub heartrate_buffer: VecDeque<HeartRateSignal>,
    50→    pub max_buffer_size: usize,
    51→    pub total_signals_collected: usize,
    52→}
    53→
    54→impl BiometricCollector {
    55→    pub fn new(max_buffer_size: usize) -> Self {
    56→        BiometricCollector {
    57→            keystroke_buffer: VecDeque::with_capacity(max_buffer_size),
    58→            touch_buffer: VecDeque::with_capacity(max_buffer_size),
    59→            heartrate_buffer: VecDeque::with_capacity(max_buffer_size),
    60→            max_buffer_size,
    61→            total_signals_collected: 0,
    62→        }
    63→    }
    64→
    65→    /// 키스트로크 신호 기록
    66→    pub fn record_keystroke(
    67→        &mut self,
    68→        key: char,
    69→        timestamp: u64,
    70→        press_duration: u64,
    71→        flight_time: u64,
    72→        pressure: f64,
    73→    ) -> bool {
    74→        let signal = KeystrokeSignal {
    75→            key,
    76→            timestamp,
    77→            press_duration,
    78→            flight_time,
    79→            pressure: pressure.clamp(0.0, 1.0),
    80→        };
    81→
    82→        if self.keystroke_buffer.len() >= self.max_buffer_size {
    83→            self.keystroke_buffer.pop_front();
    84→        }
    85→
    86→        self.keystroke_buffer.push_back(signal);
    87→        self.total_signals_collected += 1;
    88→        true
    89→    }
    90→
    91→    /// 터치 신호 기록
    92→    pub fn record_touch(
    93→        &mut self,
    94→        x: f64,
    95→        y: f64,
    96→        pressure: f64,
    97→        timestamp: u64,
    98→        duration: u64,
    99→    ) -> bool {
   100→        let signal = TouchSignal {
   101→            x,
   102→            y,
   103→            pressure: pressure.clamp(0.0, 1.0),
   104→            timestamp,
   105→            duration,
   106→        };
   107→
   108→        if self.touch_buffer.len() >= self.max_buffer_size {
   109→            self.touch_buffer.pop_front();
   110→        }
   111→
   112→        self.touch_buffer.push_back(signal);
   113→        self.total_signals_collected += 1;
   114→        true
   115→    }
   116→
   117→    /// 심박수 신호 기록 (웨어러블)
   118→    pub fn record_heartrate(
   119→        &mut self,
   120→        bpm: f64,
   121→        timestamp: u64,
   122→        variability: f64,
   123→        confidence: f64,
   124→    ) -> bool {
   125→        // 생리적 범위 검증 (40~200 BPM)
   126→        if bpm < 40.0 || bpm > 200.0 {
   127→            return false;
   128→        }
   129→
   130→        let signal = HeartRateSignal {
   131→            bpm,
   132→            timestamp,
   133→            variability: variability.clamp(0.0, 1.0),
   134→            confidence: confidence.clamp(0.0, 1.0),
   135→        };
   136→
   137→        if self.heartrate_buffer.len() >= self.max_buffer_size {
   138→            self.heartrate_buffer.pop_front();
   139→        }
   140→
   141→        self.heartrate_buffer.push_back(signal);
   142→        self.total_signals_collected += 1;
   143→        true
   144→    }
   145→
   146→    /// 타이핑 속도 분석 (WPM - Words Per Minute)
   147→    pub fn typing_speed(&self) -> f64 {
   148→        if self.keystroke_buffer.len() < 2 {
   149→            return 0.0;
   150→        }
   151→
   152→        let total_chars = self.keystroke_buffer.len();
   153→        let total_time_ms = self.keystroke_buffer
   154→            .back()
   155→            .map(|last| last.timestamp)
   156→            .unwrap_or(0)
   157→            - self.keystroke_buffer
   158→                .front()
   159→                .map(|first| first.timestamp)
   160→                .unwrap_or(0);
   161→
   162→        if total_time_ms == 0 {
   163→            return 0.0;
   164→        }
   165→
   166→        // WPM = (characters / 5) / (time in minutes)
   167→        let total_time_minutes = total_time_ms as f64 / 60000.0;
   168→        (total_chars as f64 / 5.0) / total_time_minutes
   169→    }
   170→
   171→    /// 평균 키 간 시간차 (Dwell Time)
   172→    pub fn average_dwell_time(&self) -> f64 {
   173→        if self.keystroke_buffer.is_empty() {
   174→            return 0.0;
   175→        }
   176→
   177→        let sum: u64 = self.keystroke_buffer
   178→            .iter()
   179→            .map(|s| s.press_duration)
   180→            .sum();
   181→
   182→        sum as f64 / self.keystroke_buffer.len() as f64
   183→    }
   184→
   185→    /// 평균 비행 시간 (Flight Time)
   186→    pub fn average_flight_time(&self) -> f64 {
   187→        if self.keystroke_buffer.len() < 2 {
   188→            return 0.0;
   189→        }
   190→
   191→        let sum: u64 = self.keystroke_buffer
   192→            .iter()
   193→            .map(|s| s.flight_time)
   194→            .sum();
   195→
   196→        sum as f64 / (self.keystroke_buffer.len() - 1) as f64
   197→    }
   198→
   199→    /// 평균 터치 압력
   200→    pub fn average_touch_pressure(&self) -> f64 {
   201→        if self.touch_buffer.is_empty() {
   202→            return 0.0;
   203→        }
   204→
   205→        let sum: f64 = self.touch_buffer
   206→            .iter()
   207→            .map(|s| s.pressure)
   208→            .sum();
   209→
   210→        sum / self.touch_buffer.len() as f64
   211→    }
   212→
   213→    /// 평균 심박수
   214→    pub fn average_heart_rate(&self) -> f64 {
   215→        if self.heartrate_buffer.is_empty() {
   216→            return 0.0;
   217→        }
   218→
   219→        let sum: f64 = self.heartrate_buffer
   220→            .iter()
   221→            .map(|s| s.bpm)
   222→            .sum();
   223→
   224→        sum / self.heartrate_buffer.len() as f64
   225→    }
   226→
   227→    /// 심박수 변이도 (Heart Rate Variability)
   228→    pub fn average_hrv(&self) -> f64 {
   229→        if self.heartrate_buffer.is_empty() {
   230→            return 0.0;
   231→        }
   232→
   233→        let sum: f64 = self.heartrate_buffer
   234→            .iter()
   235→            .map(|s| s.variability)
   236→            .sum();
   237→
   238→        sum / self.heartrate_buffer.len() as f64
   239→    }
   240→
   241→    /// 생체 신호 프로필 (특징 벡터)
   242→    pub fn biometric_profile(&self) -> BiometricProfile {
   243→        BiometricProfile {
   244→            typing_speed: self.typing_speed(),
   245→            dwell_time: self.average_dwell_time(),
   246→            flight_time: self.average_flight_time(),
   247→            touch_pressure: self.average_touch_pressure(),
   248→            heart_rate: self.average_heart_rate(),
   249→            heart_rate_variability: self.average_hrv(),
   250→            keystroke_count: self.keystroke_buffer.len(),
   251→            touch_count: self.touch_buffer.len(),
   252→            heartrate_count: self.heartrate_buffer.len(),
   253→        }
   254→    }
   255→
   256→    /// 버퍼 초기화
   257→    pub fn clear(&mut self) {
   258→        self.keystroke_buffer.clear();
   259→        self.touch_buffer.clear();
   260→        self.heartrate_buffer.clear();
   261→    }
   262→
   263→    /// 통계
   264→    pub fn statistics(&self) -> CollectorStatistics {
   265→        CollectorStatistics {
   266→            total_signals: self.total_signals_collected,
   267→            keystroke_buffer_size: self.keystroke_buffer.len(),
   268→            touch_buffer_size: self.touch_buffer.len(),
   269→            heartrate_buffer_size: self.heartrate_buffer.len(),
   270→            avg_keystroke_pressure: self.keystroke_buffer
   271→                .iter()
   272→                .map(|s| s.pressure)
   273→                .fold(0.0, |a, b| a + b)
   274→                / self.keystroke_buffer.len().max(1) as f64,
   275→        }
   276→    }
   277→}
   278→
   279→/// 생체 신호 프로필 (특징 벡터)
   280→#[derive(Clone, Debug)]
   281→pub struct BiometricProfile {
   282→    pub typing_speed: f64,           // WPM
   283→    pub dwell_time: f64,             // ms
   284→    pub flight_time: f64,            // ms
   285→    pub touch_pressure: f64,         // 0.0~1.0
   286→    pub heart_rate: f64,             // BPM
   287→    pub heart_rate_variability: f64, // 0.0~1.0
   288→    pub keystroke_count: usize,
   289→    pub touch_count: usize,
   290→    pub heartrate_count: usize,
   291→}
   292→
   293→/// 수집기 통계
   294→#[derive(Clone, Debug)]
   295→pub struct CollectorStatistics {
   296→    pub total_signals: usize,
   297→    pub keystroke_buffer_size: usize,
   298→    pub touch_buffer_size: usize,
   299→    pub heartrate_buffer_size: usize,
   300→    pub avg_keystroke_pressure: f64,
   301→}
   302→
   303→#[cfg(test)]
   304→mod tests {
   305→    use super::*;
   306→
   307→    #[test]
   308→    fn test_collector_creation() {
   309→        let collector = BiometricCollector::new(100);
   310→        assert_eq!(collector.keystroke_buffer.len(), 0);
   311→        assert_eq!(collector.max_buffer_size, 100);
   312→    }
   313→
   314→    #[test]
   315→    fn test_keystroke_recording() {
   316→        let mut collector = BiometricCollector::new(100);
   317→
   318→        for i in 0..10 {
   319→            collector.record_keystroke(
   320→                'a',
   321→                i as u64 * 100,
   322→                50,
   323→                100,
   324→                0.8,
   325→            );
   326→        }
   327→
   328→        assert_eq!(collector.keystroke_buffer.len(), 10);
   329→        assert_eq!(collector.total_signals_collected, 10);
   330→    }
   331→
   332→    #[test]
   333→    fn test_touch_recording() {
   334→        let mut collector = BiometricCollector::new(100);
   335→
   336→        for i in 0..5 {
   337→            collector.record_touch(
   338→                100.0 + i as f64,
   339→                200.0,
   340→                0.7,
   341→                i as u64 * 200,
   342→                50,
   343→            );
   344→        }
   345→
   346→        assert_eq!(collector.touch_buffer.len(), 5);
   347→    }
   348→
   349→    #[test]
   350→    fn test_heartrate_recording() {
   351→        let mut collector = BiometricCollector::new(100);
   352→
   353→        for i in 0..15 {
   354→            let valid = collector.record_heartrate(
   355→                72.0 + i as f64,
   356→                i as u64 * 1000,
   357→                0.5,
   358→                0.95,
   359→            );
   360→            assert!(valid);
   361→        }
   362→
   363→        assert_eq!(collector.heartrate_buffer.len(), 15);
   364→    }
   365→
   366→    #[test]
   367→    fn test_invalid_heartrate() {
   368→        let mut collector = BiometricCollector::new(100);
   369→
   370→        // 범위 외의 심박수는 거부
   371→        let valid_low = collector.record_heartrate(30.0, 0, 0.5, 0.9);
   372→        let valid_high = collector.record_heartrate(250.0, 0, 0.5, 0.9);
   373→
   374→        assert!(!valid_low);
   375→        assert!(!valid_high);
   376→    }
   377→
   378→    #[test]
   379→    fn test_biometric_profile() {
   380→        let mut collector = BiometricCollector::new(100);
   381→
   382→        for i in 0..10 {
   383→            collector.record_keystroke('a', i as u64 * 100, 50, 100, 0.8);
   384→        }
   385→
   386→        let profile = collector.biometric_profile();
   387→        assert!(profile.typing_speed > 0.0);
   388→        assert!(profile.dwell_time > 0.0);
   389→        assert_eq!(profile.keystroke_count, 10);
   390→    }
   391→
   392→    #[test]
   393→    fn test_statistics() {
   394→        let mut collector = BiometricCollector::new(100);
   395→
   396→        for i in 0..5 {
   397→            collector.record_keystroke('a', i as u64 * 100, 50, 100, 0.8);
   398→            collector.record_touch(100.0, 200.0, 0.7, i as u64 * 100, 50);
   399→            collector.record_heartrate(72.0 + i as f64, i as u64 * 100, 0.5, 0.9);
   400→        }
   401→
   402→        let stats = collector.statistics();
   403→        assert_eq!(stats.total_signals, 15);
   404→        assert_eq!(stats.keystroke_buffer_size, 5);
   405→        assert_eq!(stats.touch_buffer_size, 5);
   406→        assert_eq!(stats.heartrate_buffer_size, 5);
   407→    }
   408→}
