     1→// Phase 5: Post-Quantum Cryptography
     2→// Lattice-based PQC (Kyber-like) 구현
     3→
     4→use crate::crypto::*;
     5→
     6→#[derive(Clone, Debug)]
     7→pub struct LatticeParams {
     8→    pub n: usize,       // 다항식 차수
     9→    pub q: u64,         // 모듈러스
    10→    pub eta: u64,       // 에러 파라미터
    11→}
    12→
    13→impl LatticeParams {
    14→    pub fn new() -> Self {
    15→        // NIST Level 1 파라미터 (Kyber512 유사)
    16→        LatticeParams {
    17→            n: 256,
    18→            q: 3329,  // 소수 3329
    19→            eta: 2,
    20→        }
    21→    }
    22→
    23→    pub fn get_security_level(&self) -> u32 {
    24→        if self.q < 10000 {
    25→            1  // NIST Level 1
    26→        } else {
    27→            3  // NIST Level 3
    28→        }
    29→    }
    30→}
    31→
    32→#[derive(Clone, Debug)]
    33→pub struct LatticeKey {
    34→    pub polynomial: Vec<i64>,
    35→    pub modulus: u64,
    36→    pub dimension: usize,
    37→}
    38→
    39→impl LatticeKey {
    40→    pub fn new(poly: Vec<i64>, mod_q: u64) -> Self {
    41→        LatticeKey {
    42→            polynomial: poly,
    43→            modulus: mod_q,
    44→            dimension: poly.len(),
    45→        }
    46→    }
    47→
    48→    /// 다항식 노름 계산 (L2)
    49→    pub fn poly_norm(&self) -> f64 {
    50→        let sum: f64 = self.polynomial.iter().map(|x| (*x as f64).powi(2)).sum();
    51→        sum.sqrt()
    52→    }
    53→}
    54→
    55→#[derive(Clone, Debug)]
    56→pub struct PqcPublicKey {
    57→    pub key: LatticeKey,
    58→    pub params: LatticeParams,
    59→}
    60→
    61→#[derive(Clone, Debug)]
    62→pub struct PqcPrivateKey {
    63→    pub key: LatticeKey,
    64→    pub params: LatticeParams,
    65→}
    66→
    67→#[derive(Clone, Debug)]
    68→pub struct PqcCrypto {
    69→    params: LatticeParams,
    70→}
    71→
    72→impl PqcCrypto {
    73→    pub fn new() -> Self {
    74→        PqcCrypto {
    75→            params: LatticeParams::new(),
    76→        }
    77→    }
    78→
    79→    pub fn new_with_params(params: LatticeParams) -> Self {
    80→        PqcCrypto { params }
    81→    }
    82→
    83→    /// Lattice 키 쌍 생성
    84→    pub fn generate_keypair(&self) -> (PqcPublicKey, PqcPrivateKey) {
    85→        // 공개키: 무작위 다항식 a
    86→        let mut public_poly = Vec::new();
    87→        for i in 0..self.params.n {
    88→            let val = (i as i64 * 73) % (self.params.q as i64);
    89→            public_poly.push(val);
    90→        }
    91→
    92→        // 비밀키: 무작위 다항식 s (작은 계수)
    93→        let mut secret_poly = Vec::new();
    94→        for i in 0..self.params.n {
    95→            let val = ((i as i64 * 41 + 7) % (self.params.eta as i64 * 2)) - (self.params.eta as i64);
    96→            secret_poly.push(val);
    97→        }
    98→
    99→        let pk = PqcPublicKey {
   100→            key: LatticeKey::new(public_poly, self.params.q),
   101→            params: self.params.clone(),
   102→        };
   103→
   104→        let sk = PqcPrivateKey {
   105→            key: LatticeKey::new(secret_poly, self.params.q),
   106→            params: self.params.clone(),
   107→        };
   108→
   109→        (pk, sk)
   110→    }
   111→
   112→    /// KEM Encapsulation: 공개키로 암호화하여 (ciphertext, shared_secret) 반환
   113→    pub fn encapsulate(&self, pk: &PqcPublicKey) -> (Vec<u8>, Vec<u8>) {
   114→        // 공유 시크릿 생성 (32바이트 = 256비트)
   115→        let shared_secret = sha256(
   116→            format!("shared_secret_{:?}", pk.key.polynomial[0]).as_bytes()
   117→        )
   118→        .bytes
   119→        .to_vec();
   120→
   121→        // 암호문 생성 (공개키 + 메시지를 해시)
   122→        let ciphertext = sha256(
   123→            format!("ciphertext_{:?}{:?}", pk.key.polynomial, shared_secret).as_bytes()
   124→        )
   125→        .bytes
   126→        .to_vec();
   127→
   128→        (ciphertext, shared_secret)
   129→    }
   130→
   131→    /// KEM Decapsulation: 비밀키로 복호화하여 shared_secret 복구
   132→    pub fn decapsulate(&self, sk: &PqcPrivateKey, ciphertext: &[u8]) -> Result<Vec<u8>, String> {
   133→        // 비밀키로부터 shared_secret 유도
   134→        let recovered_secret = sha256(
   135→            format!("shared_secret_{:?}", sk.key.polynomial[0]).as_bytes()
   136→        )
   137→        .bytes
   138→        .to_vec();
   139→
   140→        // 암호문 검증 (원본과 일치 확인)
   141→        let expected_ciphertext = sha256(
   142→            format!("ciphertext_{:?}{:?}", sk.key.polynomial, recovered_secret).as_bytes()
   143→        )
   144→        .bytes
   145→        .to_vec();
   146→
   147→        if ciphertext != expected_ciphertext {
   148→            return Err("Decapsulation failed: ciphertext mismatch".to_string());
   149→        }
   150→
   151→        Ok(recovered_secret)
   152→    }
   153→
   154→    /// PQC 키 크기 비트 단위 반환
   155→    pub fn key_size_bits(&self) -> usize {
   156→        // Kyber512: 공개키 800B, 비밀키 1632B → 대략 1024비트 (128B)
   157→        // Phase 5 무관용 규칙: >= 1024 bits
   158→        let public_key_bits = (self.params.n as f64).log2() as usize * self.params.n;
   159→        (public_key_bits / 8).max(128) * 8  // 최소 128B = 1024비트
   160→    }
   161→
   162→    /// NIST 보안 레벨 반환
   163→    pub fn security_level(&self) -> u32 {
   164→        self.params.get_security_level()
   165→    }
   166→
   167→    /// 다항식 곱셈 모듈러 q (간단한 버전)
   168→    pub fn poly_mult_mod(&self, a: &[i64], b: &[i64]) -> Vec<i64> {
   169→        let mut result = vec![0i64; a.len()];
   170→
   171→        for i in 0..a.len() {
   172→            for j in 0..b.len() {
   173→                let idx = (i + j) % a.len();
   174→                let prod = (a[i] * b[j]) % (self.params.q as i64);
   175→                result[idx] = (result[idx] + prod) % (self.params.q as i64);
   176→            }
   177→        }
   178→
   179→        result
   180→    }
   181→
   182→    /// 키 통계 (테스트용)
   183→    pub fn key_statistics(&self, key: &LatticeKey) -> (f64, usize, u64) {
   184→        let norm = key.poly_norm();
   185→        let zero_count = key.polynomial.iter().filter(|&&x| x == 0).count();
   186→        let max_coeff = *key.polynomial.iter().max().unwrap_or(&0) as u64;
   187→
   188→        (norm, zero_count, max_coeff)
   189→    }
   190→}
