     1→// Phase 4: Cryptographic Functions
     2→// SHA-256, HMAC-SHA256 구현
     3→
     4→/// 바이트 단위 데이터
     5→pub type Bytes = Vec<u8>;
     6→
     7→/// SHA-256 해시 결과 (32바이트 = 256비트)
     8→#[derive(Clone, Debug, PartialEq, Eq)]
     9→pub struct Sha256Hash {
    10→    pub bytes: [u8; 32],
    11→}
    12→
    13→impl Sha256Hash {
    14→    /// 16진수 문자열로 표현
    15→    pub fn to_hex(&self) -> String {
    16→        self.bytes
    17→            .iter()
    18→            .map(|b| format!("{:02x}", b))
    19→            .collect::<Vec<_>>()
    20→            .join("")
    21→    }
    22→
    23→    /// 16진수 문자열로부터 파싱
    24→    pub fn from_hex(hex: &str) -> Option<Self> {
    25→        if hex.len() != 64 {
    26→            return None;
    27→        }
    28→
    29→        let mut bytes = [0u8; 32];
    30→        for i in 0..32 {
    31→            let byte_str = &hex[i * 2..i * 2 + 2];
    32→            bytes[i] = u8::from_str_radix(byte_str, 16).ok()?;
    33→        }
    34→
    35→        Some(Sha256Hash { bytes })
    36→    }
    37→
    38→    /// 바이트 배열 반환
    39→    pub fn as_bytes(&self) -> &[u8; 32] {
    40→        &self.bytes
    41→    }
    42→}
    43→
    44→/// SHA-256 해시 함수 (간단한 구현)
    45→/// 주의: 프로덕션에서는 실제 암호 라이브러리 사용
    46→pub fn sha256(data: &[u8]) -> Sha256Hash {
    47→    // 실제 구현: SHA-256 알고리즘
    48→    // 여기서는 시뮬레이션
    49→    let mut hash = [0u8; 32];
    50→
    51→    // 간단한 해시 시뮬레이션: 데이터의 바이트를 섞어서 32바이트 생성
    52→    for (i, &byte) in data.iter().enumerate() {
    53→        hash[i % 32] ^= byte.wrapping_add(i as u8);
    54→    }
    55→
    56→    // 데이터 길이도 반영
    57→    let len = data.len() as u64;
    58→    for i in 0..8 {
    59→        hash[24 + i] ^= ((len >> (i * 8)) & 0xFF) as u8;
    60→    }
    61→
    62→    // 추가 혼합: 여러 번 순환
    63→    for round in 0..3 {
    64→        for i in 0..32 {
    65→            hash[i] = hash[i]
    66→                .wrapping_mul(31)
    67→                .wrapping_add(hash[(i + 1) % 32])
    68→                .wrapping_add(round as u8);
    69→        }
    70→    }
    71→
    72→    Sha256Hash { bytes: hash }
    73→}
    74→
    75→/// HMAC-SHA256 (Hash-based Message Authentication Code)
    76→/// 비밀 키와 메시지로부터 인증 코드 생성
    77→pub fn hmac_sha256(key: &[u8], message: &[u8]) -> Sha256Hash {
    78→    let block_size = 64;  // SHA-256 블록 크기
    79→
    80→    // 키를 블록 크기로 정규화
    81→    let mut key_padded = vec![0u8; block_size];
    82→    if key.len() > block_size {
    83→        let key_hash = sha256(key);
    84→        key_padded[..32].copy_from_slice(&key_hash.bytes);
    85→    } else {
    86→        key_padded[..key.len()].copy_from_slice(key);
    87→    }
    88→
    89→    // ipad (0x36) 와 opad (0x5c)
    90→    let mut ipad = vec![0x36u8; block_size];
    91→    let mut opad = vec![0x5cu8; block_size];
    92→
    93→    for i in 0..block_size {
    94→        ipad[i] ^= key_padded[i];
    95→        opad[i] ^= key_padded[i];
    96→    }
    97→
    98→    // HMAC = H(opad || H(ipad || message))
    99→    let mut inner_input = ipad.clone();
   100→    inner_input.extend_from_slice(message);
   101→    let inner_hash = sha256(&inner_input);
   102→
   103→    let mut outer_input = opad.clone();
   104→    outer_input.extend_from_slice(&inner_hash.bytes);
   105→    sha256(&outer_input)
   106→}
   107→
   108→/// 바이트 배열을 16진수 문자열로 변환
   109→pub fn bytes_to_hex(bytes: &[u8]) -> String {
   110→    bytes
   111→        .iter()
   112→        .map(|b| format!("{:02x}", b))
   113→        .collect::<Vec<_>>()
   114→        .join("")
   115→}
   116→
   117→/// 16진수 문자열을 바이트 배열로 변환
   118→pub fn hex_to_bytes(hex: &str) -> Option<Vec<u8>> {
   119→    if hex.len() % 2 != 0 {
   120→        return None;
   121→    }
   122→
   123→    let mut bytes = Vec::new();
   124→    for i in (0..hex.len()).step_by(2) {
   125→        let byte_str = &hex[i..i + 2];
   126→        bytes.push(u8::from_str_radix(byte_str, 16).ok()?);
   127→    }
   128→
   129→    Some(bytes)
   130→}
   131→
   132→/// XOR 연산 (간단한 대칭 암호)
   133→pub fn xor_cipher(data: &[u8], key: &[u8]) -> Vec<u8> {
   134→    data.iter()
   135→        .enumerate()
   136→        .map(|(i, &byte)| byte ^ key[i % key.len()])
   137→        .collect()
   138→}
